-- Default content for the judicial record notifications, at platform level (organizationId NULL).
--
-- Without a row here getEmailTemplate finds nothing and sendEmailTemplate sends nothing - logging in
-- production, returning early in test - so a notification would pass its tests while being dead code.
--
-- Dutch only and deliberately plain: the subject, text, html and tiptap json are the four shapes the editor
-- round-trips, and an administrator can restyle them afterwards. No inlined stylesheet, unlike the templates
-- exported from the editor, because none of these needs one to read correctly.
INSERT INTO `email_templates` (`id`, `subject`, `groupId`, `webshopId`, `organizationId`, `type`, `text`, `html`, `json`, `updatedAt`, `createdAt`) VALUES
('3f1b7c24-5d8e-4a61-9b02-7c4e1f6a8d31', 'Een uittreksel uit het strafregister wacht op beoordeling', NULL, NULL, NULL, 'JudicialRecordAwaitingReview', '{{greeting}}\n\n{{firstNameMember}} {{lastNameMember}} heeft een uittreksel uit het strafregister afgeleverd dat niet automatisch goedgekeurd kon worden. Iemand moet het nakijken.\n\nUittreksel beoordelen:\n{{reviewUrl}}\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Een uittreksel uit het strafregister wacht op beoordeling</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>{{firstNameMember}} {{lastNameMember}} heeft een uittreksel uit het strafregister afgeleverd dat niet automatisch goedgekeurd kon worden. Iemand moet het nakijken.</p><p><br></p><div data-type="smartButton" data-id="reviewUrl"><a href="{{reviewUrl}}">Uittreksel beoordelen</a></div><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"firstNameMember"}},{"text":" ","type":"text"},{"type":"smartVariable","attrs":{"id":"lastNameMember"}},{"text":" heeft een uittreksel uit het strafregister afgeleverd dat niet automatisch goedgekeurd kon worden. Iemand moet het nakijken.","type":"text"}]},{"type":"paragraph"},{"type":"smartButton","attrs":{"id":"reviewUrl"},"content":[{"text":"Uittreksel beoordelen","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW()),
('8a2c9e31-6f4b-4d57-8e13-2b9d5c7a1f48', 'Je uittreksel uit het strafregister is goedgekeurd', NULL, NULL, NULL, 'JudicialRecordApproved', '{{greeting}}\n\nJe uittreksel uit het strafregister is nagekeken en goedgekeurd. Je hoeft nu niets te doen.\n\nDe goedkeuring blijft 3 jaar geldig. We laten je op tijd weten wanneer je een nieuw uittreksel moet afleveren.\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je uittreksel uit het strafregister is goedgekeurd</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>Je uittreksel uit het strafregister is nagekeken en goedgekeurd. Je hoeft nu niets te doen.</p><p><br></p><p>De goedkeuring blijft 3 jaar geldig. We laten je op tijd weten wanneer je een nieuw uittreksel moet afleveren.</p><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Je uittreksel uit het strafregister is nagekeken en goedgekeurd. Je hoeft nu niets te doen.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"De goedkeuring blijft 3 jaar geldig. We laten je op tijd weten wanneer je een nieuw uittreksel moet afleveren.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW()),
('c54d8b17-9a3e-4267-b1f8-6e2c4a9d7b53', 'Je uittreksel uit het strafregister is goedgekeurd onder voorwaarden', NULL, NULL, NULL, 'JudicialRecordConditionallyAccepted', '{{greeting}}\n\nJe uittreksel uit het strafregister is nagekeken en goedgekeurd, met deze voorwaarden:\n\n{{feedbackText}}\n\nHeb je hier vragen over? Antwoord dan op deze e-mail.\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je uittreksel uit het strafregister is goedgekeurd onder voorwaarden</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>Je uittreksel uit het strafregister is nagekeken en goedgekeurd, met deze voorwaarden:</p><p><br></p><p>{{feedbackText}}</p><p><br></p><p>Heb je hier vragen over? Antwoord dan op deze e-mail.</p><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Je uittreksel uit het strafregister is nagekeken en goedgekeurd, met deze voorwaarden:","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"feedbackText"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Heb je hier vragen over? Antwoord dan op deze e-mail.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW()),
('2e7f4a93-1c5d-48b6-9f27-3a8b6d1e5c94', 'Je uittreksel uit het strafregister is afgekeurd', NULL, NULL, NULL, 'JudicialRecordTemporarilyRejected', '{{greeting}}\n\nJe uittreksel uit het strafregister is nagekeken en afgekeurd. Je moet een nieuw uittreksel afleveren voor je je functie kan opnemen.\n\n{{feedbackText}}\n\nNieuw uittreksel afleveren:\n{{judicialRecordUrl}}\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je uittreksel uit het strafregister is afgekeurd</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>Je uittreksel uit het strafregister is nagekeken en afgekeurd. Je moet een nieuw uittreksel afleveren voor je je functie kan opnemen.</p><p><br></p><p>{{feedbackText}}</p><p><br></p><div data-type="smartButton" data-id="judicialRecordUrl"><a href="{{judicialRecordUrl}}">Nieuw uittreksel afleveren</a></div><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Je uittreksel uit het strafregister is nagekeken en afgekeurd. Je moet een nieuw uittreksel afleveren voor je je functie kan opnemen.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"feedbackText"}}]},{"type":"paragraph"},{"type":"smartButton","attrs":{"id":"judicialRecordUrl"},"content":[{"text":"Nieuw uittreksel afleveren","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW()),
('9b6e2d48-7f1a-4c53-8d96-5e3b7a2c9f61', 'Je uittreksel uit het strafregister is afgekeurd', NULL, NULL, NULL, 'JudicialRecordPermanentlyRejected', '{{greeting}}\n\nJe uittreksel uit het strafregister is nagekeken en definitief afgekeurd. Een nieuw uittreksel afleveren verandert die beslissing niet.\n\n{{feedbackText}}\n\nHeb je hier vragen over? Antwoord dan op deze e-mail.\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je uittreksel uit het strafregister is afgekeurd</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>Je uittreksel uit het strafregister is nagekeken en definitief afgekeurd. Een nieuw uittreksel afleveren verandert die beslissing niet.</p><p><br></p><p>{{feedbackText}}</p><p><br></p><p>Heb je hier vragen over? Antwoord dan op deze e-mail.</p><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Je uittreksel uit het strafregister is nagekeken en definitief afgekeurd. Een nieuw uittreksel afleveren verandert die beslissing niet.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"feedbackText"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Heb je hier vragen over? Antwoord dan op deze e-mail.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW()),
('6d3a8c52-4b9f-41e7-a258-1f7c9e4b3d86', 'Je uittreksel uit het strafregister verloopt binnenkort', NULL, NULL, NULL, 'JudicialRecordExpiringSoon', '{{greeting}}\n\nDe goedkeuring van je uittreksel uit het strafregister loopt af op {{validUntilDate}}. Daarna kan je je functie niet meer opnemen tot je een nieuw uittreksel hebt afgeleverd.\n\nVraag een nieuw uittreksel uit het strafregister (model 596.2) aan bij je gemeente en lever het daarna hier af.\n\nUittreksel afleveren:\n{{judicialRecordUrl}}\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je uittreksel uit het strafregister verloopt binnenkort</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>De goedkeuring van je uittreksel uit het strafregister loopt af op {{validUntilDate}}. Daarna kan je je functie niet meer opnemen tot je een nieuw uittreksel hebt afgeleverd.</p><p><br></p><p>Vraag een nieuw uittreksel uit het strafregister (model 596.2) aan bij je gemeente en lever het daarna hier af.</p><p><br></p><div data-type="smartButton" data-id="judicialRecordUrl"><a href="{{judicialRecordUrl}}">Uittreksel afleveren</a></div><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"De goedkeuring van je uittreksel uit het strafregister loopt af op ","type":"text"},{"type":"smartVariable","attrs":{"id":"validUntilDate"}},{"text":". Daarna kan je je functie niet meer opnemen tot je een nieuw uittreksel hebt afgeleverd.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Vraag een nieuw uittreksel uit het strafregister (model 596.2) aan bij je gemeente en lever het daarna hier af.","type":"text"}]},{"type":"paragraph"},{"type":"smartButton","attrs":{"id":"judicialRecordUrl"},"content":[{"text":"Uittreksel afleveren","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW())
ON DUPLICATE KEY UPDATE id=id;
